use strict;
use warnings;
use Test::More;
use ArchivePaths;

subtest benign_control => sub {
    is(ArchivePaths::destination('out', 'docs/a.txt'), 'out/docs/a.txt', 'joins the entry under out');
};

subtest security_refuses_escaping_entry => sub {
    my $returned = eval { ArchivePaths::destination('out', '../../etc/cron.d/job'); 1 };
    ok(!$returned, 'dies for an entry that leaves the destination');
};

done_testing();
